        [TestCase("try:\n    try:\n        raise ValueError('a')\n    except ValueError:\n        raise IndexError('b')\n    finally:\n        print('f')\nexcept IndexError as e:\n    print('caught', e)", "f\ncaught b", TestName = "finally_on_exception_in_handler")]
